import{_ as t,o as a,c as o,ai as n}from"./chunks/framework.Cg3BiOJh.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":1786775408000}'),r={name:"faq/index.md"};function s(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h2 id="how-do-i-add-vpp-to-my-prompts" tabindex="-1">How do I add VPP to my prompts? <a class="header-anchor" href="#how-do-i-add-vpp-to-my-prompts" aria-label="Permalink to &quot;How do I add VPP to my prompts?&quot;">​</a></h2><p>Install the VPP plugin or portable Agent Skill, then start a conversation with <code>!&lt;tag&gt; [--modifier ...]</code> on line 1. The skill uses the deterministic MCP runtime to prepare, format, and validate each exchange. See the <a href="/install/">installation guide</a>.</p><p>If the host has no skill or tool support, the <a href="/custom-instructions/">custom-instructions block</a> remains available as a reduced-assurance fallback.</p><h2 id="what-if-the-model-ignores-the-footer" tabindex="-1">What if the model ignores the footer? <a class="header-anchor" href="#what-if-the-model-ignores-the-footer" aria-label="Permalink to &quot;What if the model ignores the footer?&quot;">​</a></h2><p>The installed skill calls <code>vpp_validate_exchange</code> and can request structural repair before returning the result. In the custom-instructions fallback, treat a missing or malformed footer as a protocol violation and request correction.</p><h2 id="can-i-extend-the-tag-set" tabindex="-1">Can I extend the tag set? <a class="header-anchor" href="#can-i-extend-the-tag-set" aria-label="Permalink to &quot;Can I extend the tag set?&quot;">​</a></h2><p>Yes, but version the extension and document new tags in your implementation notes. Keep the core tags intact so other participants can interoperate.</p><h2 id="does-vpp-work-with-non-openai-models" tabindex="-1">Does VPP work with non-OpenAI models? <a class="header-anchor" href="#does-vpp-work-with-non-openai-models" aria-label="Permalink to &quot;Does VPP work with non-OpenAI models?&quot;">​</a></h2><p>Yes. Use the remote MCP endpoint when the host supports it, or the JSON/OpenAPI operations otherwise. The same deterministic core can wrap output from OpenAI, Anthropic, Gemini, or another provider.</p><h2 id="are-tag-indexes-local-to-a-locus" tabindex="-1">Are tag indexes local to a locus? <a class="header-anchor" href="#are-tag-indexes-local-to-a-locus" aria-label="Permalink to &quot;Are tag indexes local to a locus?&quot;">​</a></h2><p>No. In v1.5, each tag&#39;s index is conversation-global and continues across loci. A locus or pipeline transition resets the cycle, not the counters. Starting a new conversation with no prior state resets every counter to zero.</p><h2 id="how-should-i-handle-multi-agent-scenarios" tabindex="-1">How should I handle multi-agent scenarios? <a class="header-anchor" href="#how-should-i-handle-multi-agent-scenarios" aria-label="Permalink to &quot;How should I handle multi-agent scenarios?&quot;">​</a></h2><p>Carry one auditable <code>VppState</code> object across the orchestration boundary. Assign safe locus names for handoffs and let the runtime advance the global tag counters. Consult the normative spec when designing host-specific orchestration.</p>',13)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
